# Installs, updates or removes the PBZSuite UE4SS mod (src/PBZSuite) using a hash manifest.
# Files under runtime/ are generated by the game or the manager; Rollback archives them into evidence/.
param([Parameter(Mandatory)][ValidateSet('Install', 'Update', 'Rollback')][string]$Mode)
$ErrorActionPreference = 'Stop'
$projectRoot = Split-Path -Parent $PSScriptRoot
$sourceRoot = Join-Path $projectRoot 'src\PBZSuite'
$manifestPath = Join-Path $projectRoot 'evidence\pbzsuite-manifest.json'
$targetRoot = 'C:\Program Files (x86)\Steam\steamapps\common\PBZ\platform\steam\ue4ss\Mods\PBZSuite'
$runtimeAllowed = '^runtime\\(telemetry-[0-9a-f]+-\d+\.jsonl|config\.json|config\.json\.tmp|results\.jsonl)$'
if (Get-Process -Name PBZ -ErrorAction SilentlyContinue) { throw 'Exit PBZ normally first.' }
if (-not (Test-Path -LiteralPath 'C:\Program Files (x86)\Steam\steamapps\common\PBZ\platform\steam\ue4ss\UE4SS.dll')) { throw 'P1 loader is not installed.' }

function Get-SourceFiles {
    $full = (Resolve-Path -LiteralPath $sourceRoot).Path
    @(Get-ChildItem -LiteralPath $full -File -Recurse | ForEach-Object {
        [pscustomobject]@{ relativePath = $_.FullName.Substring($full.Length + 1); sha256 = (Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash; bytes = $_.Length }
    })
}

function Copy-Entry($entry) {
    $target = Join-Path $targetRoot $entry.relativePath
    New-Item -ItemType Directory -Path (Split-Path -Parent $target) -Force | Out-Null
    Copy-Item -LiteralPath (Join-Path $sourceRoot $entry.relativePath) -Destination $target -Force
    if ((Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash -ne $entry.sha256) { throw "Copy hash mismatch: $($entry.relativePath)" }
}

function Save-Manifest($manifest) { $manifest | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $manifestPath -Encoding utf8 }

# Every installed file must still match the manifest; returns the validated absolute paths.
function Assert-Installed($manifest) {
    $validated = @()
    foreach ($entry in $manifest.files) {
        $target = [IO.Path]::GetFullPath((Join-Path $targetRoot $entry.relativePath))
        if (-not $target.StartsWith($targetRoot + '\', [StringComparison]::OrdinalIgnoreCase)) { throw 'Path outside PBZSuite directory.' }
        if (-not (Test-Path -LiteralPath $target -PathType Leaf)) { throw "Missing recorded file: $($entry.relativePath)" }
        if ((Get-FileHash -LiteralPath $target -Algorithm SHA256).Hash -ne $entry.sha256) { throw "Modified file; aborting: $($entry.relativePath)" }
        $validated += $target
    }
    $validated
}

if ($Mode -eq 'Install') {
    if (Test-Path -LiteralPath $manifestPath) { throw 'Manifest exists; use Update or Rollback.' }
    if (Test-Path -LiteralPath $targetRoot) { throw 'PBZSuite already exists in game directory; inspect ownership.' }
    $files = Get-SourceFiles
    $manifest = [ordered]@{ product = 'PBZSuite'; destination = $targetRoot; status = 'PLANNED'; files = $files }
    Save-Manifest $manifest
    foreach ($entry in $files) { Copy-Entry $entry }
    $manifest.status = 'INSTALLED'
    $manifest.installedAt = (Get-Date).ToString('o')
    Save-Manifest $manifest
    Write-Output "Installed $($files.Count) files."
    return
}

$manifest = Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json
$validated = Assert-Installed $manifest

if ($Mode -eq 'Update') {
    $files = Get-SourceFiles
    $old = @{}
    foreach ($entry in $manifest.files) { $old[$entry.relativePath] = $entry }
    $changed = 0
    foreach ($entry in $files) {
        if (-not $old.ContainsKey($entry.relativePath) -or $old[$entry.relativePath].sha256 -ne $entry.sha256) {
            if (-not $old.ContainsKey($entry.relativePath) -and (Test-Path -LiteralPath (Join-Path $targetRoot $entry.relativePath))) { throw "Untracked target exists: $($entry.relativePath)" }
            Copy-Entry $entry
            $changed++
        }
    }
    $newPaths = $files | ForEach-Object relativePath
    foreach ($entry in $manifest.files) {
        if ($entry.relativePath -notin $newPaths) { Remove-Item -LiteralPath (Join-Path $targetRoot $entry.relativePath); $changed++ }
    }
    $updated = [ordered]@{ product = 'PBZSuite'; destination = $targetRoot; status = 'INSTALLED'; files = $files; installedAt = $manifest.installedAt; updatedAt = (Get-Date).ToString('o') }
    Save-Manifest $updated
    Write-Output "Updated $changed files."
    return
}

$targetFull = $targetRoot
$unknown = @(Get-ChildItem -LiteralPath $targetFull -File -Recurse | Where-Object { $_.FullName -notin $validated })
$archive = Join-Path $projectRoot ('evidence\pbzsuite-runtime-' + (Get-Date -Format yyyyMMdd-HHmmss))
foreach ($file in $unknown) {
    $relative = $file.FullName.Substring($targetFull.Length + 1)
    if ($relative -notmatch $runtimeAllowed) { throw "Unknown file found; inspect manually before rollback: $relative" }
}
foreach ($file in $unknown) {
    $relative = $file.FullName.Substring($targetFull.Length + 1)
    $dest = Join-Path $archive $relative
    New-Item -ItemType Directory -Path (Split-Path -Parent $dest) -Force | Out-Null
    Copy-Item -LiteralPath $file.FullName -Destination $dest
}
foreach ($target in $validated) { Remove-Item -LiteralPath $target }
foreach ($file in $unknown) { Remove-Item -LiteralPath $file.FullName }
$directories = @(Get-ChildItem -LiteralPath $targetFull -Directory -Recurse | Sort-Object { $_.FullName.Length } -Descending)
foreach ($directory in $directories) { [IO.Directory]::Delete($directory.FullName, $false) }
[IO.Directory]::Delete($targetFull, $false)
Move-Item -LiteralPath $manifestPath -Destination (Join-Path $projectRoot ('evidence\pbzsuite-manifest-removed-' + (Get-Date -Format yyyyMMdd-HHmmss) + '.json'))
Write-Output "Rollback complete; $($unknown.Count) runtime files archived."
